-- Migration: Add category and image_url to public.exercises and populate metadata
-- Allows the frontend to load and display all 900+ exercises directly from the database
-- without bundling massive JSON files into the client cache.

ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS category text;
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS image_url text;

